    {
      "category": "interest_aggregation",
      "rationale": "Blend each recurrent state with its causal recency-weighted pooled history: 90% current state and 10% pooling with a five-step half-life. Training and prediction share this readout through the predictor's existing GRU4RecModel import.",
      "edits": [
        {
          "find": "        return pooled.to(out.dtype)",
          "replace": "        return 0.9 * out + 0.1 * pooled.to(out.dtype)"
        }
      ]
    }
  ],
  "change_summary": "Apply the specified 90/10 recurrent-state and recency-pooling blend across all four category models, preserving the GRU backbone and training configuration."
}
